import React, { useState, useEffect, useCallback, useRef } from "react";
import { createClient } from "@supabase/supabase-js";

// ─── SUPABASE ─────────────────────────────────────────────────────────────────
const SUPABASE_URL = "https://qvibdnrfywisvfsqgqux.supabase.co";
const SUPABASE_ANON = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InF2aWJkbnJmeXdpc3Zmc3FncXV4Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzg4OTE5MTcsImV4cCI6MjA5NDQ2NzkxN30.qPNjcpQpHPV5_SVz3U-JC18CcZ6vxio9vImA3CKg5jk";
const sb = createClient(SUPABASE_URL, SUPABASE_ANON);

// ─── PERIOD KEYS (server-side reset logic via keys, not deletes) ──────────────
const dailyKey = () => new Date().toLocaleDateString("sv-SE", { timeZone: "Europe/Malta" });
const weeklyKey = () => {
  const now = new Date(new Date().toLocaleString("en-US", { timeZone: "Europe/Malta" }));
  const day = now.getDay();
  const diff = now.getDate() - day + (day === 0 ? -6 : 1);
  return new Date(now.setDate(diff)).toLocaleDateString("sv-SE");
};
const monthlyKey = () => new Date().toLocaleDateString("sv-SE", { timeZone: "Europe/Malta" }).slice(0, 7);

// ─── STATIC DATA ─────────────────────────────────────────────────────────────
const ROOMS = [
  { id: "ensuite", label: "Ensuite" },
  { id: "main_bath", label: "Main Bathroom" },
  { id: "main_bed", label: "Main Bedroom" },
  { id: "girls_bed", label: "Girls' Bedroom" },
  { id: "finn", label: "Finn's Room" },
  { id: "open", label: "Open Plan Kitchen/Living/Dining" },
];

const PLANNING_EVENTS_INIT = [
  { id: "pl1", text: "Plan Father's Day", date: "31/05/2026", trigger_month: "05/2026", notes: "" , recurring: true },
  { id: "pl2", text: "Plan Josh's Birthday", date: "20/06/2026", trigger_month: "06/2026", notes: "" , recurring: true },
  { id: "pl3", text: "Summer Opening Ceremony", date: "28/06/2026", trigger_month: "06/2026", notes: "Pool set up, ice cream, pizza or hot dogs" , recurring: true },
  { id: "pl4", text: "Plan Finley's Birthday", date: "09/08/2026", trigger_month: "08/2026", notes: "" , recurring: true },
  { id: "pl5", text: "Plan Anniversary", date: "05/09/2026", trigger_month: "09/2026", notes: "" , recurring: true },
  { id: "pl6", text: "Summer Closing Down Ceremony", date: "20/09/2026", trigger_month: "09/2026", notes: "Last swim Saturday, drain + put away pool, pizza + ice cream on the turf" , recurring: true },
  { id: "pl7", text: "Plan Mum's Birthday", date: "04/10/2026", trigger_month: "10/2026", notes: "" , recurring: true },
  { id: "pl8", text: "Plan Halloween", date: "01/10/2026", trigger_month: "10/2026", notes: "" , recurring: true },
  { id: "pl9", text: "Plan Freya's Birthday", date: "07/11/2026", trigger_month: "11/2026", notes: "" , recurring: true },
  { id: "pl10", text: "Plan Christmas", date: "28/11/2026", trigger_month: "11/2026", notes: "" , recurring: true },
  { id: "pl11", text: "Plan Easter", date: "29/03/2027", trigger_month: "03/2027", notes: "Celebration and basket" , recurring: true },
  { id: "pl12", text: "Plan Valentine's Day", date: "31/01/2027", trigger_month: "01/2027", notes: "Valentine's basket, breakfast + dinner treats, date with Josh, decor" , recurring: true },
  { id: "pl13", text: "Plan Flossy's Birthday", date: "15/02/2027", trigger_month: "02/2027", notes: "" , recurring: true },
  { id: "pl14", text: "Plan Mother's Day", date: "01/05/2027", trigger_month: "04/2027", notes: "Check: 7 wine glasses, 7 plates main, 7 plates side. Buy: pink napkins, pink runner" , recurring: true },
];

// Helper: roll trigger month forward 1 year
const advanceTriggerMonth = (tm) => {
  if (!tm) return tm;
  const [m, y] = tm.split("/");
  return `${m}/${parseInt(y) + 1}`;
};

const JOSH_AGENDA = [
  "Review the week",
  "Next week — what needs doing",
  "Dates / social planning",
  "Anything on your mind",
];

const JOSH_ACTIONS = [
  "Christmas booking",
  "Reebok passport office",
  "Decide if we are camping",
  "Plan laundry room project",
  "Discuss going out more + spreadsheet",
];

// ─── GOOGLE CALENDAR ─────────────────────────────────────────────────────────
const GOOGLE_CALENDAR_CLIENT_ID = "1002245234804-rfko6k6qlk315l0uugn5ejngv6q8klcm.apps.googleusercontent.com";
const GOOGLE_CALENDAR_SCOPE = "https://www.googleapis.com/auth/calendar.readonly";

const loadScript = (id, src) => new Promise((resolve, reject) => {
  const existing = document.getElementById(id);
  if (existing) {
    if (window.google?.accounts?.oauth2) return resolve();
    const started = Date.now();
    const check = setInterval(() => {
      if (window.google?.accounts?.oauth2) {
        clearInterval(check);
        resolve();
      } else if (Date.now() - started > 10000) {
        clearInterval(check);
        reject(new Error(`${id} timed out`));
      }
    }, 100);
    return;
  }
  const script = document.createElement("script");
  script.id = id;
  script.src = src;
  script.async = true;
  script.defer = true;
  const timer = setTimeout(() => reject(new Error(`${id} timed out`)), 10000);
  script.onload = () => { clearTimeout(timer); resolve(); };
  script.onerror = () => { clearTimeout(timer); reject(new Error(`${id} failed`)); };
  document.head.appendChild(script);
});

const calendarDayBounds = () => {
  const now = new Date(new Date().toLocaleString("en-US", { timeZone: "Europe/Malta" }));
  const start = new Date(now);
  start.setHours(0, 0, 0, 0);
  const end = new Date(start);
  end.setDate(end.getDate() + 1);
  return { start: start.toISOString(), end: end.toISOString() };
};

const eventStartDate = (event) => event.start?.dateTime || event.start?.date || "";
const eventEndDate = (event) => event.end?.dateTime || event.end?.date || "";
const isAllDayEvent = (event) => Boolean(event.start?.date);

const eventTimeLabel = (event) => {
  if (isAllDayEvent(event)) return "All day";
  const start = eventStartDate(event);
  const end = eventEndDate(event);
  if (!start) return "";
  const fmt = { hour: "2-digit", minute: "2-digit", hour12: false, timeZone: "Europe/Malta" };
  const s = new Date(start).toLocaleTimeString("en-GB", fmt);
  const e = end ? new Date(end).toLocaleTimeString("en-GB", fmt) : "";
  return e ? `${s}–${e}` : s;
};

const normalizeCalendarEvent = (event, calendar) => ({
  id: `${calendar.id}_${event.id}`,
  calendarId: calendar.id,
  calendarName: calendar.summary || "Calendar",
  color: calendar.backgroundColor || "var(--admin)",
  title: event.summary || "(No title)",
  start: eventStartDate(event),
  end: eventEndDate(event),
  allDay: isAllDayEvent(event),
  timeLabel: eventTimeLabel(event),
  location: event.location || "",
  description: event.description || "",
  htmlLink: event.htmlLink || "",
});

function useGoogleCalendar() {
  const [ready, setReady] = useState(false);
  const [authed, setAuthed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [calendars, setCalendars] = useState([]);
  const [todayEvents, setTodayEvents] = useState([]);
  const [error, setError] = useState(null);
  const [accessToken, setAccessToken] = useState(null);
  const tokenClientRef = useRef(null);

  const init = useCallback(async () => {
    if (ready) return;
    setError(null);
    try {
      await loadScript("google-identity-services", "https://accounts.google.com/gsi/client");
      tokenClientRef.current = window.google.accounts.oauth2.initTokenClient({
        client_id: GOOGLE_CALENDAR_CLIENT_ID,
        scope: GOOGLE_CALENDAR_SCOPE,
        callback: () => {},
      });
      setReady(true);
    } catch (e) {
      console.error(e);
      setError("Couldn't initialise Google Calendar.");
    }
  }, [ready]);

  useEffect(() => { init(); }, [init]);

  const calendarFetch = useCallback(async (path, token) => {
    const res = await fetch(`https://www.googleapis.com/calendar/v3/${path}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok) throw new Error(`Google Calendar request failed: ${res.status}`);
    return res.json();
  }, []);

  const loadCalendarData = useCallback(async (token = accessToken) => {
    if (!token) return;
    setLoading(true);
    setError(null);
    try {
      const { start, end } = calendarDayBounds();
      const calendarRes = await calendarFetch("users/me/calendarList?minAccessRole=reader", token);
      const list = (calendarRes.items || []).filter(c => c.selected !== false);
      const eventGroups = await Promise.all(list.map(async (calendar) => {
        try {
          const params = new URLSearchParams({
            timeMin: start,
            timeMax: end,
            singleEvents: "true",
            orderBy: "startTime",
            maxResults: "50",
          });
          const res = await calendarFetch(`calendars/${encodeURIComponent(calendar.id)}/events?${params}`, token);
          return (res.items || []).map(event => normalizeCalendarEvent(event, calendar));
        } catch (e) {
          console.warn("Calendar load failed", calendar.summary, e);
          return [];
        }
      }));
      const events = eventGroups.flat().sort((a, b) => {
        if (a.allDay && !b.allDay) return -1;
        if (!a.allDay && b.allDay) return 1;
        return (a.start || "").localeCompare(b.start || "");
      });
      setCalendars(list);
      setTodayEvents(events);
      setAuthed(true);
    } catch (e) {
      console.error(e);
      setError("Couldn't load Google Calendar.");
    }
    setLoading(false);
  }, [accessToken, calendarFetch]);

  const signIn = useCallback(async () => {
    await init();
    if (!tokenClientRef.current) return;
    tokenClientRef.current.callback = async (resp) => {
      if (resp.error) {
        setError("Google sign-in was cancelled.");
        return;
      }
      setAccessToken(resp.access_token);
      await loadCalendarData(resp.access_token);
    };
    tokenClientRef.current.requestAccessToken({ prompt: accessToken ? "" : "consent" });
  }, [accessToken, init, loadCalendarData]);

  const signOut = useCallback(() => {
    if (accessToken) window.google?.accounts?.oauth2?.revoke(accessToken);
    setAccessToken(null);
    setAuthed(false);
    setCalendars([]);
    setTodayEvents([]);
  }, [accessToken]);

  const refresh = useCallback(async () => {
    if (!accessToken) {
      await signIn();
    } else {
      await loadCalendarData(accessToken);
    }
  }, [accessToken, loadCalendarData, signIn]);

  return { ready, authed, loading, calendars, todayEvents, error, signIn, signOut, refresh };
}

