        width: size, height: size, borderRadius: size * 0.3,
        border: `1.5px solid ${checked ? color : "var(--border)"}`,
        background: checked ? color : "transparent",
        flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center",
